insert into public.items (name, kind, description) values ('Strange Potion I', 'potion', 'A random blessing/curse that lasts 5 minutes (300s) from {The List I}. * {The List I} **The Chosen: +150% (+1.5) Luck & +30% Roll Speed. **The Power I: +150% Luck. **The Knowledge I: +30% Roll Speed. **The Wrath I: -50% Luck. **The Sloth I: -15% Roll Speed. • Obtained from: *Obtained from traveling merchant, Jester.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Strange Potion II', 'potion', 'A random blessing/curse that lasts 10 minutes (600s) from {The List II}. * {The List II} ** GODLIKE: +250% (+2.5) Luck & +40% Roll Speed. ** The Power II: +250 (+2.5) Luck. ** The Knowledge II: +40% Roll Speed. ** The Wrath II: -100% Luck. ** The Sloth II: -25% Roll Speed. • Obtained from: *Obtained from traveling merchant, Jester.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
