insert into public.items (name, kind, description) values ('Coin', 'misc', 'Grants 50$ • Obtained from: The player can find these around the map at different spawn locations, every 20 seconds with an unknown spawn chance.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Gilded Coin', 'misc', 'Grants 100$ • Obtained from: The player can find these around the map at different spawn locations, every 20 seconds with an unknown spawn chance.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Void Coin', 'misc', 'Used for purchasing items from the Jester. • Obtained from: The Void Coin can be obtained through the ''''I give my life...'''' and ''''[10,000,000]'''' Achievements, bought from Mari for $500,000 or be collected with a 0.02% per hour at night. It can be used to buy the Oblivion Potion for 5 Void Coin.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Lucky Penny', 'misc', 'It applies a +77% Luck and +7% Roll Speed permanent bonus. • Obtained from: Purchasable from Mari. Every 10 minutes, the penny has a 5% chance to disappear from the user''s inventory.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Gear A', 'misc', 'Used to upgrade the Bank. • Obtained from: Obtained from traveling merchant, Mari.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Gear B', 'misc', 'Used to upgrade the Bank. • Obtained from: Obtained from traveling merchant, Mari.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Stella''s Star', 'misc', 'When given to Stella, she will open a portal that allows the player to fast travel directly to her cave instead of having to do the parkour. It also creates a portal at her cave so that the player can exit immediately. • Obtained from: During Starfall biome, the item has a chance of spawning at a random location.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Stella''s Candle', 'misc', 'Stella''s Candle can be bought from Jester for 50 Dark Points. It provides a 20 minute luck boost. Stella''s Candle grants a +20% luck boost to any player nearby. Only 2 candles can be purchased at a time. • Obtained from: Obtained from traveling merchant, Jester.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Random Potion Sack', 'misc', 'Random Potion Sack is an item that can be bought from the Jester for 10 Dark Points, and has a max stock of 10. When used, it randomly selects a type of potion, and grants it to the user. • Obtained from: Obtained from traveling merchant, Jester.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Strange Controller', 'misc', 'An item capable of changing the biome with respect to the biome''s rarity, unlike it''s stronger counterpart. Contrary to popular belief, this device and it''s counterpart ''''CAN'''' spawn the Glitched Biome, which stays at its normal rarity of 1 in 30k. This item has a 20 minute cooldown and a server-wide cooldown of 10 minutes. • Obtained from: Crafted at Jake''s Workshop. *1x NULL? *1x Eternal Flame *1x Piece of Star *1x Curruptaine *1x Rainy Bottle *1x Icicle *1x Wind Essence') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Biome Randomizer', 'misc', 'An item capable of changing the biome to a random biome regardless of the biome''s rarity (Every biome, excluding Glitched (Which stays at it''s normal rarity), will have a 1/7 chance of spawning), thus making it an extremely powerful luxury tool. This item has a cooldown of 35 minutes, more than it''s weaker counterpart, and has a server-wide cooldown of 20 minutes. • Obtained from: Crafted at Jake''s Workshop. *1x Undefined *1x Hades *1x Poseidon *1x Galaxy *1x Astral *1x Permafrost *1x Stormal *4x Strange Controller') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Biome Selector', 'misc', 'A device capable of changing the biome on command (Does not apply to Rare Biomes/Event Biomes) This item has a cooldown of 1 hour. • Obtained from: Crafted at Jake''s Workshop. *1x Biome Randomizer *1x Cyber Technology') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Rainbow Syrup', 'misc', 'Used in the Summer 2024 quest, "Lime''s Hwachae Recipe". • Obtained from: Purchasable from Mari for $3000.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Hwachae', 'misc', 'Grants +100% Luck and +25% Roll Speed for one hour, when used. • Obtained from: Rewarded from the Summer 2024 quest, "Lime''s Hwachae Recipe".') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Merchant Teleporter', 'misc', 'Teleports you to a merchant once used, if one has already spawned. • Obtained from: Bought for in the Gamepass Store.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Merchant Tracker', 'misc', 'Indicates where a merchant is, if one has already spawned. • Obtained from: Bought for 1000P from the Jester.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Pumpkin', 'misc', 'Can be used to exchange with Jack The Pumpkin for Pump Token, however, now that the halloween event is over, you are able to use 1 pumpkin to get 150% luck for 10 rolls each. • Obtained from: Can be found around the map.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Pump King''s Head', 'misc', 'Can be used to exchange with Jack The Pumpkin for 100 Pump Token. • Obtained from: Has a rare chance to spawn on the map.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Random Potion Sack', 'misc', 'N/A • Obtained from: The Random Potion Sack is an item obtained from an achievement known as “The Sommelier”.') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
insert into public.items (name, kind, description) values ('Rune of Wind', 'rune', 'Rune of Wind is an item added in the Era 8 Update, and can be obtained by finishing the “Breakthrough”, "Break the Limit", “Break the Galaxy” and "Break the Reality" achievements. Other than achievements, it can be obtained from the Jester, achieved From Quests, or from Random Rune Chest. When Run') on conflict (name) do update set kind = excluded.kind, description = excluded.description;
